public class CentsRounder {

    public static long toCents(double amount) {
        long size = Math.round(Math.abs(amount) * 100.0);
        if (amount < 0) {
            return -size;
        }
        return size;
    }

    public static String format(long cents) {
        String sign = "";
        if (cents < 0) {
            sign = "-";
        }
        long size = Math.abs(cents);
        long dollars = size / 100;
        long pennies = size % 100;
        return sign + "$" + dollars + "." + String.format("%02d", pennies);
    }
}
